#!/usr/bin/env python3
"""Independent native-face CT and physical thermal audit of saved final volumes.

Uses the saved spherical face geometry, including Athena volume centers.
Cell-centered reconstructed divergence is a different diagnostic.
"""
from pathlib import Path
from datetime import datetime, timezone
import argparse, hashlib, json, sys
import numpy as np

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts'))
from audit_entropy_bound import audit as entropy_audit


def audit(folder):
    folder=folder.resolve()
    fields_path=sorted(folder.glob('snapshot_*.npy'))[-1]
    z=np.load(fields_path,mmap_mode='r')
    if z.ndim!=4 or z.shape[-1]!=8:
        raise ValueError('A native eight-field primitive volume is required')
    nr,nt,np_=z.shape[:3]
    if nr*nt*np_>1_300_000:
        raise ValueError('This whole-array audit is bounded to1.3million cells')
    rf,tf,pf=[np.load(folder/name) for name in ['r_faces_au.npy','theta_faces_rad.npy','phi_faces_rad.npy']]
    r,theta,phi=[np.load(folder/name) for name in ['r_au.npy','theta_rad.npy','phi_rad.npy']]
    if [len(rf),len(tf),len(pf)]!=[nr+1,nt+1,np_+1]:
        raise ValueError('Face/volume shapes disagree')
    for faces,centers in [(rf,r),(tf,theta),(pf,phi)]:
        if np.any(np.diff(faces)<=0) or not np.all((centers>faces[:-1])&(centers<faces[1:])):
            raise ValueError('Centers must lie inside their actual saved faces')
    if np.max(np.abs(np.diff(pf)-np.diff(pf)[0]))>1e-12 or abs(pf[-1]-pf[0]-2*np.pi)>1e-12:
        raise ValueError('The native audit requires periodic, uniform full longitude')
    dp=np.diff(pf)[0]
    br,bt,bp=[np.load(folder/name,mmap_mode='r') for name in ['Br_faces_nt.npy','Btheta_faces_nt.npy','Bphi_faces_nt.npy']]
    if br.shape!=(nr+1,nt,np_) or bt.shape!=(nr,nt+1,np_) or bp.shape!=(nr,nt,np_+1):
        raise ValueError('Native face component shape mismatch')
    ar=rf[:,None,None]**2*(np.cos(tf[:-1])-np.cos(tf[1:]))[None,:,None]*dp
    at=.5*np.diff(rf**2)[:,None,None]*np.sin(tf)[None,:,None]*dp
    ap=.5*np.diff(rf**2)[:,None,None]*np.diff(tf)[None,:,None]
    volume=np.diff(rf**3)[:,None,None]/3*(np.cos(tf[:-1])-np.cos(tf[1:]))[None,:,None]*dp
    fr=np.asarray(br)*ar;ft=np.asarray(bt)*at;fp=np.asarray(bp)*ap
    circulation=np.diff(fr,axis=0)+np.diff(ft,axis=1)+np.diff(fp,axis=2)
    div=circulation/volume
    bmag=np.linalg.norm(np.asarray(z[...,5:8]),axis=-1)
    h=volume**(1/3)
    eps=np.divide(h*np.abs(div),bmag,out=np.zeros_like(div),where=bmag>0)
    temperature=np.asarray(z[...,4])*1e-9/(2*np.asarray(z[...,0])*1e6*1.380649e-23)
    speed=np.linalg.norm(np.asarray(z[...,1:4]),axis=-1)*1000
    rho=np.asarray(z[...,0])*1e6*1.67262192369e-27
    force=np.divide(bmag*np.abs(div)*1e-18*r[:,None,None],1.25663706212e-6*rho*speed**2,
                    out=np.full_like(div,np.nan),where=speed>0)
    fluxscale=np.abs(fr[1:])+np.abs(fr[:-1])+np.abs(ft[:,1:])+np.abs(ft[:,:-1])+np.abs(fp[:,:,1:])+np.abs(fp[:,:,:-1])
    incidence=np.divide(np.abs(circulation),fluxscale,out=np.zeros_like(div),where=fluxscale>0)
    denom=float(np.sum(bmag*volume))
    report={'case':folder.name,'volume_sha256':hashlib.sha256(fields_path.read_bytes()).hexdigest(),
            'shape_r_theta_phi':[nr,nt,np_],
            'method':'Exact spherical face-area flux incidence using saved native CT faces; no midpoint reinterpretation of volume centers.',
            'maximum_absolute_divB_nT_per_AU':float(np.max(np.abs(div))),
            'maximum_absolute_cell_flux_residual_nT_AU2':float(np.max(np.abs(circulation))),
            'maximum_cell_flux_residual_over_unsigned_face_flux':float(np.max(incidence)),
            'weighted_hdivB_over_B':float(np.sum(h*np.abs(div)*volume)/denom) if denom else None,
            'percentile95_hdivB_over_B':float(np.percentile(eps,95)) if denom else None,
            'maximum_monopole_force_over_inertia':float(np.nanmax(force)) if np.any(np.isfinite(force)) else None,
            'longitude_seam_face_field_max_difference_nT':float(np.max(np.abs(bp[:,:,0]-bp[:,:,-1]))),
            'all_volume_fields_finite':bool(np.all(np.isfinite(z))),
            'all_volume_density_pressure_positive':bool(np.all(z[...,0]>0)&np.all(z[...,4]>0)),
            'minimum_temperature_K':float(np.min(temperature)),
            'number_cells_below1000K':int(np.sum(temperature<1000)),
            'thermal_caveat':'Final saved volume only. Native divergence is distinct from a centered reconstructed derivative.'}
    cfg=dict(line.split('=',1) for line in (folder/'run.cfg').read_text().splitlines() if '=' in line)
    if cfg.get('boundary_speed_thermo_closure')=='1' and not cfg.get('cme_boundary_csv'):
        report['entropy_bound']=entropy_audit(folder)
    trace=folder/'ct_trace.csv'
    if trace.exists():
        a=np.genfromtxt(trace,delimiter=',',names=True,ndmin=1)
        report['accepted_step_trace']={'rows':len(a),'start_day':float(a['day'][0]),'end_day':float(a['day'][-1]),
            'maximum_native_face_divB_code_all_saved_steps':float(np.max(a['max_native_face_divB_code'])),
            'maximum_target_B_error_code_all_saved_steps':float(np.max(a['max_inner_target_B_code_error']))}
    return report


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('folders',nargs='+',type=Path)
    parser.add_argument('--output',type=Path,default=ROOT/'validation/ct_fields_audit.json')
    args=parser.parse_args()
    result={'author':'Codex-root','created_utc':datetime.now(timezone.utc).isoformat(),
            'cases':{p.name:audit(p) for p in args.folders}}
    args.output.parent.mkdir(parents=True,exist_ok=True)
    args.output.write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    print(json.dumps(result,indent=2,allow_nan=False))


if __name__=='__main__':
    main()
#!/usr/bin/env python3
"""Derive comet-frame incident flux, exposure weighting and scientific figures."""
from pathlib import Path
import csv, json, hashlib
from datetime import datetime, timezone
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from astropy.time import Time
from run_records import completed_output
from observer_clock import observer_case

ROOT=Path(__file__).resolve().parents[1]
ORIGIN=60980.
OBS=ROOT/'observations'; FIG=ROOT/'figures'
WINDOW=(Time('2025-12-03T12:37:38').mjd-ORIGIN,Time('2025-12-04T17:22:29').mjd-ORIGIN)

def tsv(path):
    return np.genfromtxt(path,names=True,delimiter='\t',dtype=None,encoding='utf8')

def csv_table(path):
    return np.genfromtxt(path,names=True,delimiter=',')

def comet_velocity(day):
    e=tsv(OBS/'ephemeris_comet.tsv')
    basis=np.array(json.loads((OBS/'coordinate_system.json').read_text())['ecliptic_to_solar_equatorial_matrix'])
    pos=np.array([np.interp(day+ORIGIN,e['mjd_utc'],e[k]) for k in ['x_au','y_au','z_au']]).T@basis.T
    vel=np.array([np.interp(day+ORIGIN,e['mjd_utc'],e[k]) for k in ['vx_au_day','vy_au_day','vz_au_day']]).T@basis.T*149597870.7/86400
    r=np.linalg.norm(pos,axis=-1); phi=np.arctan2(pos[:,1],pos[:,0]);theta=np.arccos(pos[:,2]/r)
    er=pos/r[:,None]; et=np.array([np.cos(theta)*np.cos(phi),np.cos(theta)*np.sin(phi),-np.sin(theta)]).T
    ep=np.array([-np.sin(phi),np.cos(phi),np.zeros_like(phi)]).T
    return np.array([np.sum(vel*vec,axis=-1) for vec in [er,et,ep]]).T

def own_case(name,folder=None):
    a=csv_table((folder or ROOT/'results'/name)/'probe.csv');a=a[a['probe_id']==0]
    vc=comet_velocity(a['day'])
    w=np.column_stack([a['vr_kms'],a['vtheta_kms'],a['vphi_kms']])
    rel=np.linalg.norm(w-vc,axis=1)
    return {'day':a['day'],'n':a['n_cm3'],'v':a['speed_kms'],'f':a['flux_cm2_s'],
        'v_rel':rel,'f_incident':a['n_cm3']*rel*1e5}

def ccmc_case(key):
    z=np.load(ROOT/'external_model/ccmc_profiles.npz');fields=list(z['fields']);a=z[key]
    d={str(k):a[:,j] for j,k in enumerate(fields)};day=d['mjd']-ORIGIN
    use=(day>=14)&(day<=34);d={k:v[use] for k,v in d.items()};day=day[use]
    vc=comet_velocity(day)
    # ENLIL RTN uses T east and N north; solver theta points south.
    w=np.column_stack([d['vr_kms'],-d['vn_kms'],d['vt_kms']])
    rel=np.linalg.norm(w-vc,axis=1)
    return {'day':day,'n':d['n_cm3'],'v':d['speed_kms'],'f':d['flux_cm2_s'],
        'v_rel':rel,'f_incident':d['n_cm3']*rel*1e5}

def integrate(a,key,start,stop):
    if start<a['day'][0]-1e-8 or stop>a['day'][-1]+1e-8:raise ValueError('Refusing temporal extrapolation in GTI integral')
    inside=a['day'][(a['day']>start)&(a['day']<stop)]
    knots=np.r_[start,inside,stop]
    return np.trapezoid(np.interp(knots,a['day'],a[key]),knots)

def stats(a,spans):
    duration=sum(b-s for s,b in spans)
    return {key:sum(integrate(a,key,s,b) for s,b in spans)/duration for key in ['n','v','f','v_rel','f_incident']}

def relative_comparison(a,b,window=WINDOW):
    if any(window[0]<x['day'][0]-1e-8 or window[1]>x['day'][-1]+1e-8 for x in [a,b]):raise ValueError('Refusing temporal extrapolation in convergence comparison')
    t=np.unique(np.r_[window[0],a['day'][(a['day']>window[0])&(a['day']<window[1])],b['day'][(b['day']>window[0])&(b['day']<window[1])],window[1]])
    ratios={k:np.interp(t,a['day'],a[k])/np.interp(t,b['day'],b[k])-1 for k in ['n','v','f','f_incident']}
    return {k:{'maximum_relative_difference':float(np.max(np.abs(delta))),
        'median_relative_difference':float(np.median(delta)),
        'rms_relative_difference':float(np.sqrt(np.mean(delta**2)))} for k,delta in ratios.items()}

def exposure_comparison(a,b,spans,frames):
    """Exact means and L1 difference of the piecewise-linear probe curves."""
    left,right=stats(a,spans),stats(b,spans)
    fields=['n','v','f_incident']
    frame_changes={str(frame):{k:stats(a,windows)[k]/stats(b,windows)[k]-1 for k in fields}
                   for frame,windows in frames.items()}
    l1={}
    for k in fields:
        numerator=denominator=0.
        for start,stop in spans:
            if any(start<x['day'][0]-1e-8 or stop>x['day'][-1]+1e-8 for x in [a,b]):
                raise ValueError('Refusing exposure-comparison extrapolation')
            t=np.unique(np.r_[start,stop,a['day'][(a['day']>start)&(a['day']<stop)],b['day'][(b['day']>start)&(b['day']<stop)]])
            delta=np.interp(t,a['day'],a[k])-np.interp(t,b['day'],b[k])
            cross=np.flatnonzero(delta[:-1]*delta[1:]<0)
            roots=t[cross]-delta[cross]*(t[cross+1]-t[cross])/(delta[cross+1]-delta[cross])
            knots=np.unique(np.r_[t,roots])
            av=np.interp(knots,a['day'],a[k]);bv=np.interp(knots,b['day'],b[k])
            numerator+=np.trapezoid(abs(av-bv),knots)
            denominator+=np.trapezoid(abs(bv),knots)
        l1[k]=float(numerator/denominator)
    return {'PN_GTI_mean_relative_change':{k:float(left[k]/right[k]-1) for k in fields},
            'PN_frame_GTI_mean_relative_changes':frame_changes,
            'maximum_absolute_frame_GTI_mean_relative_change':{k:float(max(abs(x[k]) for x in frame_changes.values())) for k in fields},
            'PN_GTI_integrated_absolute_curve_difference_over_fine_integral':l1,
            'definition':'Exact trapezoidal integration of native piecewise-linear curves, with exact GTI endpoints and every difference sign crossing; no fitted shift or extrapolation.'}

def main():
    FIG.mkdir(exist_ok=True)
    cases={p.name:own_case(p.name) for p in (ROOT/'results').iterdir() if completed_output(p) and p.name not in ['pilot','interrupted_wide_medium']}
    selection_path=ROOT/'results/reference_selection.json'
    selection=json.loads(selection_path.read_text()) if selection_path.exists() else {}
    best=selection.get('reference_case') or next(k for k in ['wide_fine','wide_medium','fine','medium','coarse'] if k in cases)
    if best not in cases:raise ValueError('Selected reference is not a completed simulation')
    comparisons={'ccmc_cme':ccmc_case('3I-Atlas1'),'ccmc_ambient':ccmc_case('3I-Atlas2amb')}
    scheme_cases={}
    for name,dirname in [('split_coarse','coarse_split_glm'),('split_medium','medium_split_glm')]:
        directory=ROOT/'solver/experiments'/dirname
        if (directory/'statistics.json').exists():scheme_cases[name]=own_case(name,folder=directory)
    allcases={k:observer_case(a,selection) for k,a in {**cases,**comparisons,**scheme_cases}.items()}
    gti=tsv(OBS/'xmm_gtis.tsv');gti=gti[gti['detector']=='pn']
    spans=list(zip(gti['start_mjd_utc']-ORIGIN,gti['stop_mjd_utc']-ORIGIN))
    baseline=json.loads((OBS/'baseline_result.json').read_text())
    baseline_spans=[tuple(Time(baseline['observation_utc']).mjd-ORIGIN)]
    summary={'reference_case':best,'published_window_day':WINDOW,'PN_good_exposure_seconds':sum(b-a for a,b in spans)*86400,
        'time_convention':selection.get('time_convention','simultaneous_geometric_UTC'),
        'time_convention_details':'Selected means, output curves and selected-reference controls use the requested comparison clock. Historical numerical/method tables use the original simultaneous geometric UTC convention. Observer-arrival mapping uses geometric Earth as XMM proxy and same-emission-epoch comet velocity; final light-time audit independently checks interpolation/quadrature.',
        'definitions':{'n':'proton number density, cm^-3','v':'heliocentric bulk speed, km/s',
            'f':'conventional heliocentric proton flux n|vSW|, cm^-2 s^-1',
            'v_rel':'comet-frame relative wind speed |vSW-vComet|, km/s',
            'f_incident':'incident proton flux n|vSW-vComet|, cm^-2 s^-1'},
        'cases':{},'numerical_comparisons':{},'parameter_comparisons':{},'scheme_comparisons':{},'boundary_comparisons':{},'accelerated_comparisons':{},
        'reference_selection':selection,
        'caveat':'Parameter min/max envelope is a sensitivity range, not a confidence interval. No contemporaneous heavy-ion abundance measured at the comet.'}
    for name,a in allcases.items():
        knots=np.unique(np.r_[WINDOW[0],a['day'][(a['day']>WINDOW[0])&(a['day']<WINDOW[1])],WINDOW[1]])
        summary['cases'][name]={'PN_GTI_weighted_mean':stats(a,spans),'analysis06_window_mean':stats(a,baseline_spans),
            'published_window':{k:{'min':float(np.interp(knots,a['day'],a[k]).min()),'median':float(np.median(np.interp(knots,a['day'],a[k]))),
                'max':float(np.interp(knots,a['day'],a[k]).max())} for k in ['n','v','f','v_rel','f_incident']}}
    for left,right in [('coarse','medium'),('medium','fine'),('time_half','medium'),('wide_coarse','coarse'),('domain45','wide_coarse'),('domain75','wide_coarse'),('wide_coarse','wide_medium'),('wide_medium','wide_fine'),('fine','wide_fine'),('wide_movie','wide_medium'),('frozen_magnetic','frozen_medium'),('frozen_split','frozen_medium_split')]:
        if left in cases and right in cases: summary['numerical_comparisons'][left+'_vs_'+right]=relative_comparison(cases[left],cases[right])
    for name,a in cases.items():
        if not name.startswith(('cuda','cme_','ct')) and name not in ['coarse','medium','fine','time_half','wide_coarse','wide_medium','wide_fine','domain45','domain75','wide_movie','frozen_split','frozen_medium_split','outer_scaled','outer_scaled_split','inductive_coarse','inductive_coarse_split','inductive_zero_control']:
            base='medium' if name=='frozen_medium' else 'coarse'
            summary['parameter_comparisons'][name+'_vs_'+base]=relative_comparison(a,cases[base])
    for name,a in scheme_cases.items():
        baseline='coarse' if name=='split_coarse' else 'medium'
        summary['scheme_comparisons'][name+'_vs_'+baseline]=relative_comparison(a,cases[baseline])
    for left,right in [('frozen_split','frozen_magnetic'),('frozen_medium_split','frozen_medium'),('outer_scaled_split','outer_scaled'),('inductive_coarse_split','inductive_coarse')]:
        if left in cases and right in cases:summary['scheme_comparisons'][left+'_vs_'+right]=relative_comparison(cases[left],cases[right])
    for left,right in [('outer_scaled','coarse'),('inductive_coarse','outer_scaled'),('inductive_coarse_split','outer_scaled_split'),('inductive_zero_control','coarse'),('cme_coarse_split','outer_scaled_split'),('cme_long_coarse_split','outer_scaled_split'),('cme_long_coarse_split','cme_coarse_split')]:
        if left in cases and right in cases:summary['boundary_comparisons'][left+'_vs_'+right]=relative_comparison(cases[left],cases[right])
    accelerated_pairs=[]
    for variant in ['global','split']:
        accelerated_pairs.extend([(f'cuda_{variant}96',f'cuda_{variant}144'),(f'cuda_{variant}144',f'cuda_{variant}192')])
    accelerated_pairs.extend([(f'cuda_global{n}',f'cuda_split{n}') for n in [96,144,192]])
    accelerated_pairs.extend([('cuda_global96_half','cuda_global96'),('cuda_split192_half','cuda_split192'),
        ('cuda_inductive96','cuda_split96'),('cuda_inductive192','cuda_split192'),
        ('cuda_width45','cuda_split192'),('cuda_width75','cuda_split192')])
    for left,right in accelerated_pairs:
        if left in cases and right in cases:summary['accelerated_comparisons'][left+'_vs_'+right]=relative_comparison(cases[left],cases[right])
    accelerated32=[]
    for variant in ['global','split']:
        accelerated32.extend([(f'cuda32_{variant}96',f'cuda32_{variant}144'),(f'cuda32_{variant}144',f'cuda32_{variant}192'),(f'cuda32_{variant}192',f'cuda32_{variant}288')])
    accelerated32.extend([(f'cuda32_global{n}',f'cuda32_split{n}') for n in [96,144,192,288]])
    accelerated32.extend([('cuda32_global96','cuda_global96'),('cuda32_global96_half','cuda32_global96'),
        ('cuda32_split192_half','cuda32_split192'),('cuda32_inductive192','cuda32_split192')])
    for left,right in accelerated32:
        if left in cases and right in cases:summary['accelerated_comparisons'][left+'_vs_'+right]=relative_comparison(cases[left],cases[right])
    balanced=[]
    for variant in ['global','split','hlle','hlld']:
        balanced.extend([(f'cuda32_bal_{variant}96',f'cuda32_bal_{variant}144'),(f'cuda32_bal_{variant}144',f'cuda32_bal_{variant}192')])
    for n in [96,144,192]:
        balanced.extend([(f'cuda32_bal_global{n}',f'cuda32_bal_split{n}'),(f'cuda32_bal_hlle{n}',f'cuda32_bal_split{n}'),(f'cuda32_bal_hlld{n}',f'cuda32_bal_hlle{n}')])
        balanced.extend([(f'cuda32_th_hlld{n}',f'cuda32_bal_hlld{n}'),(f'cuda32_loc_hlld{n}',f'cuda32_th_hlld{n}')])
        balanced.append((f'cuda32_loc45_hlld{n}',f'cuda32_loc_hlld{n}'))
    for family in ['th','loc','loc45','jh','jh45','jp','jp45']:
        balanced.extend([(f'cuda32_{family}_hlld96',f'cuda32_{family}_hlld144'),(f'cuda32_{family}_hlld144',f'cuda32_{family}_hlld192')])
    for n in [96,144,192]:
        balanced.extend([(f'cuda32_jp45_hlld{n}',f'cuda32_jp_hlld{n}'),(f'cuda32_jp_hlld{n}',f'cuda32_th_hlld{n}')])
    balanced.append(('cuda32_jp_hlld96_half','cuda32_jp_hlld96'))
    for label in ['cooler','hotter','density_low','density_high','inductive','cme','cme_long','outer']:
        balanced.append((f'cuda32_jp_hlld96_{label}','cuda32_jp_hlld96'))
    balanced.extend([('cuda32_bal_global96','cuda32_global96'),('cuda32_bal_split96','cuda32_split96'),
        ('cuda32_th_hlld96_half','cuda32_th_hlld96'),
        ('cuda32_bal_half192','cuda32_bal_split192'),('cuda32_bal_wide75','cuda32_bal_split192'),
        ('cuda32_bal_inductive192','cuda32_bal_split192'),('cuda32_bal_cme192','cuda32_bal_split192'),
        ('cuda32_bal_cme_long192','cuda32_bal_split192')])
    for left,right in balanced:
        if left in cases and right in cases:summary['accelerated_comparisons'][left+'_vs_'+right]=relative_comparison(cases[left],cases[right])
    # The final selection records which controls apply to its actual equations
    # and inputs; historical fixed-method passes remain separate above.
    final_checks={}
    for category in ['spatial','temporal','domain','physics']:
        final_checks[category]=[]
        for left,right in selection.get(category+'_comparisons',[]):
            comparison=relative_comparison(allcases[left],allcases[right])
            limits={'n':.10,'v':.05,'f_incident':.10} if category=='spatial' else ({'n':.01,'v':.01,'f_incident':.01} if category=='temporal' else None)
            final_checks[category].append({'left':left,'right':right,'comparison':comparison,
                'targets':limits,'passed':all(comparison[k]['maximum_relative_difference']<=value for k,value in limits.items()) if limits else None})
    summary['selected_reference_checks']=final_checks
    observable_plan=ROOT/'validation/ct_convergence_plan.json'
    observable_targets=json.loads(observable_plan.read_text()).get('exposure_observable_metrics',{}) if observable_plan.exists() else {}
    summary['selected_observable_checks']=[]
    frame_spans={str(frame):list(zip(gti[gti['frame']==frame]['start_mjd_utc']-ORIGIN,gti[gti['frame']==frame]['stop_mjd_utc']-ORIGIN)) for frame in np.unique(gti['frame'])}
    if observable_targets:
        metrics=[('PN_GTI_mean_relative_change','PN_GTI_mean_relative_targets'),
                 ('maximum_absolute_frame_GTI_mean_relative_change','maximum_individual_PN_frame_GTI_mean_relative_targets'),
