def parallel_equivalence(parallel,serial,plan):
    lp,rp=completion(parallel),completion(serial)
    if not(lp['execution_complete'] and rp['execution_complete']):return {'status':'pending','parallel':str(parallel),'serial_reference':str(serial),'reason':'Both explicit cases must independently complete','parallel_completion':{k:lp[k] for k in ['status','reasons']},'serial_completion':{k:rp[k] for k in ['status','reasons']}}
    if parallel.resolve()==serial.resolve():return {'status':'not_compared','reason':'Parallel and serial paths are identical; this is not an independent equivalence test'}
    target=plan['parallel_gates']['maximum_field_and_probe_difference_normalized_to_physical_scale']
    # Each channel normalized to its own global amplitude. Signed near-zero
    # samples are never used as relative denominators. Native coordinates may
    # differ by measured block-decomposition roundoff.
    result={'status':'compared','parallel':str(parallel),'serial_reference':str(serial),'normalization':'Each channel maximum absolute serial amplitude; zero channel uses1 in the channel native units. No tiny pointwise signed denominator.','target':target,'arrays':{}}
    maxdiff=0
    for name in NATIVE_FILES+[Path(lp['volume_path']).name]:
        x=np.load(parallel/name,mmap_mode='r');y=np.load(serial/name,mmap_mode='r')
        if x.shape!=y.shape:raise ValueError('Parallel equivalence shape mismatch: '+name)
        scale=np.max(np.abs(y),axis=tuple(range(y.ndim-1))) if name==Path(lp['volume_path']).name else float(np.max(np.abs(y)))
        scale=np.where(scale>0,scale,1.)
        delta=np.max(np.abs(x-y),axis=tuple(range(y.ndim-1))) if name==Path(lp['volume_path']).name else float(np.max(np.abs(x-y)))
        normalized=delta/scale;maxdiff=max(maxdiff,float(np.max(normalized)))
        result['arrays'][name]={'byte_identical':sha(parallel/name)==sha(serial/name),'maximum_absolute_difference':np.atleast_1d(delta).tolist(),'maximum_difference_over_serial_channel_scale':np.atleast_1d(normalized).tolist()}
        del x,y
    a=np.genfromtxt(parallel/'probe.csv',delimiter=',',names=True,ndmin=1);b=np.genfromtxt(serial/'probe.csv',delimiter=',',names=True,ndmin=1)
    if a.shape!=b.shape or a.dtype.names!=b.dtype.names:raise ValueError('Parallel probe row/schema mismatch')
    result['probe']={}
    for k in a.dtype.names:
        d=float(np.max(np.abs(a[k]-b[k])));s=float(np.max(np.abs(b[k])));scaled=d/(s if s>0 else 1)
        maxdiff=max(maxdiff,scaled);result['probe'][k]={'maximum_absolute_difference':d,'maximum_difference_over_serial_channel_scale':scaled}
    result['probe_byte_identical']=sha(parallel/'probe.csv')==sha(serial/'probe.csv')
    x=np.genfromtxt(parallel/'stage_trace.csv',delimiter=',',names=True,ndmin=1);y=np.genfromtxt(serial/'stage_trace.csv',delimiter=',',names=True,ndmin=1)
    if x.shape!=y.shape:raise ValueError('Parallel stage trace row mismatch')
    epoch=max(float(np.max(abs(x[k]-y[k]))/max(float(np.max(abs(y[k]))),1e-99)) for k in ['base_day','full_dt','rhs_day'])
    s,t=lp['statistics'],rp['statistics']
    result['steps_identical']=s['steps']==t['steps'];result['physical_stage_calls_identical']=s['stage_calls']==t['stage_calls'];result['stage_epoch_maximum_relative_difference']=epoch
    result['common_statistics']={k:{'parallel':v,'serial':t[k],'absolute_difference':abs(v-t[k]) if isinstance(v,(float,int)) else None} for k,v in s.items() if k in t}
    budget=max(abs(float(s[k])-float(t[k])) for k in ['max_mass_budget_relative_error','max_energy_budget_relative_error'])
    result.update(maximum_field_and_probe_scaled_difference=maxdiff,budget_difference=budget,passed=bool(maxdiff<=target and result['steps_identical'] and result['physical_stage_calls_identical'] and epoch<=plan['parallel_gates']['stage_epoch_relative_difference_target'] and budget<=plan['parallel_gates']['budget_difference_target']),scope='Long-run numerical equivalence of these explicit runs, not scientific accuracy or mesh convergence.')
    return result

